def get_metrics(model_list, #перечень моделей
                model_name_list, #имена моделй
                X_test, y_test #тестовый массив
                ):
  #списки под метрики
  accuracy_score_list = []
  precision_score_list = []
  recall_score_list = []
  f1_score_list = []
  roc_auc_score_list = []

  #полотно для plotly
  fig = go.Figure()
  fig.add_shape(type = 'line',
                line = dict(dash = 'dash'),
                x0=0, x1=1, y0=0, y1=1)

  #идем в цикле по каждой модели в списке
  for i in range(len(model_list)):
    y_pred = model_list[i].predict(X_test)
    print(f"для модели {model_name_list[i]} \n")

    print("Confusion matrix = ")
    print(confusion_matrix(y_test, y_pred, labels=[1,0]))
    print(f"Accuracy =  {accuracy_score(y_test, y_pred)}")
    print(f"precision_score =  {precision_score(y_test, y_pred)}")
    print(f"Recall =  {recall_score(y_test, y_pred)}")
    print(f"f1 =  {f1_score(y_test, y_pred)}")
    print(f"ROC_AUC = {roc_auc_score(y_test, y_pred)}")
    print('==============================')

    #добавлем метрики в список
    accuracy_score_list.append(accuracy_score(y_test, y_pred))
    precision_score_list.append(precision_score(y_test, y_pred))
    recall_score_list.append(recall_score(y_test, y_pred))
    f1_score_list.append(f1_score(y_test, y_pred))
    roc_auc_score_list.append(roc_auc_score(y_test, y_pred))

    #tpr, fpr
    fpr, tpr, _ = roc_curve(y_test, y_pred) #fpr tpr
    auc_score = roc_auc_score(y_test, y_pred)

    #нанести график на полотно
    name = f"{model_name_list[i]} (AUC = {auc_score})" #имя модели + значение площади
    fig.add_trace(go.Scatter(x = fpr,
                             y = tpr,
                             name = name,
                             mode = 'lines'))

  #обновить наше полотно с FPR TPR
  fig.update_layout(xaxis_title = 'FPR',
                    yaxis_title = 'TPR',
                    yaxis = dict(scaleanchor = "x", scaleratio = 1),
                    xaxis = dict(constrain="domain"),
                    width = 900, height = 600)

  ploted_figure = fig.show()

  #собираем общий датарфейм с метриками
  result_table = pd.DataFrame(index = model_name_list)
  result_table['accuracy'] = accuracy_score_list
  result_table['precision'] = precision_score_list
  result_table['recall'] = recall_score_list
  result_table['f1'] = f1_score_list
  result_table['roc_auc'] = roc_auc_score_list

  return result_table, ploted_figure

result_table, ploted_figure = get_metrics(model_list, model_name_list, X_test, y_test )

result_table

ploted_figure

